        function buildCore(tt) {
          const R = tt.core;
          if (!R)
            throw new Error("Game chưa mở tuTien.core. Hãy cập nhật game.");
          const K = {
            gameVersion: tt.gameVersion,
            bundle: "v" + tt.gameVersion,
            healed: [],
            healFail: [],
            optMissing: [],
          };
          const miss = [];
          for (const [key, mod, name] of CORE_REQUIRED) {
            const f = R[mod] && R[mod][name];
            if (f === undefined) miss.push(mod + "." + name);
            else K[key] = f;
          }
          if (miss.length)
            throw new Error(
              "Game vừa cập nhật nên Tool chưa nhận ra: " +
                miss.join(", ") +
                ". Hãy chụp màn hình này gửi Claude để sửa Tool.",
            );
          for (const [key, mod, name, label] of CORE_OPTIONAL) {
            const f = R[mod] && R[mod][name];
            if (f !== undefined) K[key] = f;
            else K.optMissing.push(label + " (" + mod + "." + name + ")");
          }
          // Lưới kinh mạch: khuonCua(content, nhânVật). ctx có đủ .items nên truyền thẳng được.
          const KM = R["character/kinh_mach"];
          K.luoiKinhMach = (c, nv) => KM.khuonCua(c, nv);
          // Hằng đọc sống từ game (hằng khai 'export let' đổi theo độ khó), không chép ra biến lúc nạp.
          const live = (name, mod, key) =>
            Object.defineProperty(K, name, {
              enumerable: true,
              get() {
                try {
                  const v = R[mod][key];
                  return v === undefined ? undefined : v;
                } catch (e) {
                  return undefined;
                }
              },
            });
          live(
            "AMBUSH_MIN_DISTANCE",
            "balance/encounter",
            "AMBUSH_MIN_DISTANCE",
          );
          live("CAP_BAC", "balance/sect", "CAP_BAC"); // tên cấp bậc tông môn: Tạp dịch … Trưởng lão
          if (!Array.isArray(K.CAP_BAC) || !K.CAP_BAC.length)
            throw new Error(
              "Game vừa cập nhật nên Tool chưa nhận ra: balance/sect.CAP_BAC (tên cấp bậc tông môn). Hãy chụp màn hình này gửi Claude để sửa Tool.",
            );
          const numArr = (a, n) =>
            Array.isArray(a) &&
            (n === undefined || a.length === n) &&
            a.every(Number.isFinite);
          Object.defineProperty(K, "bm", {
            enumerable: true,
            get() {
              try {
                const N = R["balance/natal"],
                  o = {};
                for (const [k, nm] of Object.entries(BM_CONST)) o[k] = N[nm];
                const arr6 = [
                  "teYears",
                  "teEss",
                  "upEss",
                  "hoaYears",
                  "tempEss",
                  "ess",
                  "fail",
                  "byp",
                ];
                const ok =
                  arr6.every((k) => numArr(o[k], 6)) &&
                  numArr(o.tier, 4) &&
                  numArr(o.mult, 4) &&
                  numArr(o.slotT, 4) &&
                  numArr(o.runeLv, 2) &&
                  Object.entries(o).every(([k, v]) =>
                    Array.isArray(v)
                      ? v.every(Number.isFinite)
                      : Number.isFinite(v),
                  );
                return ok ? o : undefined;
              } catch (e) {
                return undefined;
              }
            },
          });
          Object.defineProperty(K, "bmRune", {
            enumerable: true,
            get() {
              try {
                const o = R["balance/natal"].NATAL_RUNE_VALUE;
                return o &&
                  BM_RUNE_KEYS.every((k) => numArr(o[k], 5) || numArr(o[k], 3))
                  ? o
                  : undefined;
              } catch (e) {
                return undefined;
              }
            },
          });
          Object.defineProperty(K, "rare", {
            enumerable: true,
            get() {
              try {
                const C = R["balance/combat"],
                  dH = C.RARE_DROP_CHANCE,
                  rank = C.RARE_DROP_RANK_FACTOR;
                if (
                  !numArr(dH) ||
                  !rank ||
                  !Object.values(rank).every(Number.isFinite)
                )
                  return undefined;
                return { dH, rank, nhanHo: TC_RARE.nhanHo };
              } catch (e) {
                return undefined;
              }
            },
          });
          Object.defineProperty(K, "san", {
            enumerable: true,
            get() {
              try {
                const E = R["balance/encounter"],
                  max = E.HUNTS_PER_SLOT,
                  hoi = E.HUNT_RECOVERY_YEARS;
                return max > 0 && hoi > 0 ? { max, hoi } : undefined;
              } catch (e) {
                return undefined;
              }
            },
          });
          // Săn cạn: số lần tối đa mỗi nơi và số năm hồi một lần (đọc lại mỗi lần vẽ vì hằng có thể đổi theo độ khó).
          K.sync = () => {
            const s = K.san;
            if (s) {
              AU_T4 = s.max;
              AU_ZAN = s.hoi;
            }
          };
          K.sync();
          return K;
        }
        // Nạp lõi: đồng bộ (tuTien.core có sẵn từ pha ready). Giữ dạng async để các chỗ gọi cũ không phải đổi.
        async function loadCore(progress) {
          const g = G();
          if (!g || !g.env || !g.env.content)
            throw new Error(
              "Chưa thấy game. Hãy đợi game tải xong rồi bấm Thử Lại.",
            );
          progress("Đang nối lõi game…");
          return buildCore(TT);
        }

        // ───────────────────────── 2. Tiện ích ─────────────────────────
        const G = () => TT.game;
        const C = () => G().env.content;
        const HUD = () => TT.hud;
        const gamePanel = (name, open) =>
          TT.ui && TT.ui.gamePanel ? TT.ui.gamePanel(name, open) : false;
        const clone = (x) => structuredClone(x);
        const sleep0 = () => new Promise((r) => setTimeout(r, 0));
        const pct = (x, d = 0) => (x * 100).toFixed(d).replace(".", ",") + "%";
        const num = (x, d = 1) =>
          (Math.round(x * 10 ** d) / 10 ** d).toString().replace(".", ",");
        const esc = (s) =>
          String(s ?? "").replace(
            /[&<>"]/g,
            (c) =>
              ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" })[c],
          );
        const HE = {
          kim: "Kim",
          moc: "Mộc",
          thuy: "Thủy",
          hoa: "Hỏa",
          tho: "Thổ",
          bang: "Băng",
          loi: "Lôi",
          phong: "Phong",
          am: "Ám",
          vo_sac: "Vô sắc",
        };
        const heTen = (h) => HE[h] ?? h;
        const STAGE = ["Sơ", "Trung", "Hậu", "ĐVM"];

        function ctx(opts) {
          const rc = G().readCtx && G().readCtx(opts); // ctx chính thức của game, dựng trên bản sao kiếp đang chơi
          if (rc) return rc;
          const K = S.core,
            st = G().state;
          const run = clone(st.run),
            meta = clone(st.meta),
            F = K.Rng,
            o = new Map();
          run.rngKeys ??= {};
          return {
            ...G().env,
            run,
            meta,
            rng: new F(run.rng),
            enc: run.active,
            noticeLines: [],
            rngFor(r) {
              let u = o.get(r);
              if (!u) {
                const l = Object.hasOwn(run.rngKeys, r)
                  ? run.rngKeys[r]
                  : undefined;
                u =
                  l === undefined
                    ? F.fromSeed(`${run.seed}|rng|${r}`)
                    : new F(l);
                o.set(r, u);
              }
              return u;
            },
          };
        }
        const nvNow = () => clone(G().state.run.nhanVat);
        const REALM_TEN = [
          "Phàm Nhân",
          "Luyện Khí",
          "Trúc Cơ",
          "Kết Đan",
          "Nguyên Anh",
          "Hóa Thần",
        ];
        const realmName = (i) => {
          try {
            return S.core.canhGioi(i).ten;
          } catch {
            return REALM_TEN[i] || "Cảnh Giới " + i;
          }
        };
        const realmLabel = (cg, tc) => {
          try {
            return S.core.tenCanhGioi(cg, tc);
          } catch {
            return realmName(cg);
          }
        };

        // ───────────────────────── 3. Mô phỏng trận ─────────────────────────
        const BENCH_IDS = [
          "enemy.de_tu_truc_co",
          "enemy.doc_hanh_kiem_khach",
          "enemy.ma_tu_hut_mau",
          "enemy.cuong_thi",
          "enemy.am_tuong",
          "enemy.lao_hoe_tinh",
          "enemy.hoa_tinh",
          "enemy.thuy_linh",
          "enemy.mao_cuong",
        ];
        function benchEnemies(cg, tcP = 0) {
          const K = S.core,
            c = C();
          const tcs = [Math.max(0, tcP - 1), tcP, Math.min(3, tcP + 1)];
          let ids = BENCH_IDS.filter((id) => c.enemies.has(id));
          if (ids.length < 6) {
            const all = [...c.enemies.keys()].sort();
            const step = Math.max(1, Math.floor(all.length / 9));
            ids = all.filter((_, i) => i % step === 0).slice(0, 9);
          }
          return ids.map((id, i) => ({
            id,
            E: K.taoBenDich(
              {
                ...c.enemies.get(id),
                canh_gioi: cg,
                tieu_canh_gioi: tcs[i % 3],
              },
              c,
              { muc: "thuong" },
            ),
          }));
        }
        function fight(P, E) {
          try {
            return S.core.tinhTocChien(clone(P), clone(E), {});
          } catch {
            return { thang: false, nHiep: 30, khiHuyetThapNhat: 0, stTa: 0 };
          }
        }
        function enemyAt(def, cg, tc, muc) {
          return S.core.taoBenDich(
            { ...def, canh_gioi: cg, tieu_canh_gioi: tc },
            C(),
            muc ? { muc } : {},
          );
        }

        // ───────────────────────── 4. Tối ưu kinh mạch ─────────────────────────
        // ───────────────────────── Hướng xếp: Tiên Tu (tương sinh) / Ma Tu (tương khắc) + ưu tiên linh căn & huyệt ─────────────────────────
        // Điểm cộng thêm ngoài điểm do chính code game tính (K.tinhKinhMach/K.taoBenTa). Trọng số là ước lượng của tool, không phải số liệu game.
        const SINH_HE = {
          kim: "thuy",
          thuy: "moc",
          moc: "hoa",
          hoa: "tho",
          tho: "kim",
        };
        const KHAC_HE = {
          kim: "moc",
          moc: "tho",
          tho: "thuy",
          thuy: "hoa",
          hoa: "kim",
        };
        const GOC_HE = { loi: "moc", phong: "moc", bang: "thuy", am: "thuy" };
        const gocHe = (h) => GOC_HE[h] || h;
        const heTacDong = (a, b) => {
          const x = gocHe(a),
            y = gocHe(b);
          return SINH_HE[x] === y ? 1 : KHAC_HE[x] === y ? -1 : 0;
        };
        /* ═════ BẢN 6.14: Ô KINH MẠCH HỢP HỆ (sinh · được sinh · cùng gốc) ═════
     Ô hệ X dùng được: X và hệ cùng gốc (Băng ~ Thủy; Lôi, Phong ~ Mộc), hệ sinh ra X, hệ mà X sinh ra (cùng với các hệ cùng gốc của chúng).
     Ví dụ ô Thủy: Thủy, Băng (cùng gốc) · Kim (Kim sinh Thủy) · Mộc, Lôi, Phong (Thủy sinh Mộc). */
        const HOP_W = { dung: 1, goc: 0.5, sinh: 0 }; // 6.19: đúng hàm l0n của game: đúng hệ 1, cùng gốc 0,5, còn lại 0 (tương sinh với ô KHÔNG được tính)
        const sinhRa = (h) => SINH_HE[gocHe(h)];
        const sinhBoi = (h) =>
          Object.keys(SINH_HE).find((k) => SINH_HE[k] === gocHe(h));
        const khacBoi = (h) =>
          Object.keys(KHAC_HE).find((k) => KHAC_HE[k] === gocHe(h));
        const hoHe = (g) =>
          [
            "kim",
            "moc",
            "thuy",
            "hoa",
            "tho",
            "bang",
            "loi",
            "phong",
            "am",
          ].filter((h) => gocHe(h) === g);
        function oHop(cell, he) {
          if (!cell || !he || cell === "vo_sac" || he === "vo_sac") return 0;
          if (cell === he) return HOP_W.dung;
          const c = gocHe(cell),
            h = gocHe(he);
          if (c === h) return HOP_W.goc;
          return SINH_HE[c] === h || SINH_HE[h] === c ? HOP_W.sinh : 0;
        }
        // Ô khắc hệ món (đúng hàm ja của game): món nằm quá nửa trên ô khắc nó thì +1 điểm nghịch.
        const oKhac = (cell, he) =>
          !!cell &&
          !!he &&
          cell !== "vo_sac" &&
          he !== "vo_sac" &&
          KHAC_HE[gocHe(cell)] === gocHe(he);
        function oDungDuoc(cell) {
          const c = gocHe(cell);
          return hoHe(c); // 6.19: chỉ đúng hệ và cùng gốc; game không tính tương sinh giữa món và ô
        }
        S.dir = S.dir || "";
        if (S.prio === undefined) S.prio = true;
        S.full = false;
        /* đã bỏ Xếp Full Ô */ if (S.biasK === undefined) S.biasK = 5;
        // Tập huyệt đúng code game mới (hV / sV): vị trí huyệt thật = km.huyetGoc (game xê dịch huyệt của khuôn sang ô kề cùng vòng khi tạo kiếp;
        // kiếp cũ chưa có huyetGoc thì dùng huyệt của khuôn) cộng huyệt phụ km.huyetThem. Bản game cũ chỉ tính huyệt phụ khi khuôn có huyệt tự nhiên và
        // không có huyetGoc; luật đó đã bỏ, nên Hoang Cổ Thánh Thể (khuôn không huyệt) nay vẫn nhận huyệt phụ.
        function hySet(g, km) {
          if (S.core && S.core.acupointsOf && g && km) {
            try {
              const res = S.core.acupointsOf(g, km);
              if (res instanceof Set) return res;
              if (Array.isArray(res)) return new Set(res);
            } catch (e) {}
          }
          const base = Array.isArray(km && km.huyetGoc)
            ? km.huyetGoc
            : ((g && g.huyet) || []).flatMap((v, i) => (v ? [i] : []));
          return new Set([...base, ...((km && km.huyetThem) || [])]);
        }
        function biasCtx(nv0, g) {
          const dir = S.dir || "",
            prio = !!S.prio,
            bk = S.kmBuild || "";
          if (!dir && !prio && !bk) return null;
          const km = nv0.kinhMach;
          const hy = hySet(g, km); // đúng code game mới (hV / sV), xem hySet
          return {
            dir,
            prio,
            rong: g.rong,
            mau: km.mau || [],
            hy,
            lc: new Set((nv0.linhCan && nv0.linhCan.he) || []),
            lcRoot: new Set(((nv0.linhCan && nv0.linhCan.he) || []).map(gocHe)),
            items: C().items,
            build: bk ? BUILDS.find((x) => x.k === bk) || null : null,
          };
        }
        function biasInfo(B, manh, R) {
          const f = {
            sinh: 0,
            khac: 0,
            hop: 0,
            lech: 0,
            trungTinh: 0,
            lc: 0,
            lcGoc: 0,
            lcKhac: 0,
            huyet: 0,
            build: 0,
            bhuyet: 0,
          };
          const own = new Map();
          manh.forEach((p, i) => p.cells.forEach((x) => own.set(x, i)));
          const hes = manh.map((p) => {
            const it = B.items.get(p.m.item);
            return ((it && it.he) || []).filter((h) => h && h !== "vo_sac");
          });
          const thong = (i) => !R || !R.manh || !R.manh[i] || R.manh[i].thong;
          manh.forEach((p, i) => {
            if (!thong(i)) return;
            const nb = new Set();
            for (const c of p.cells) {
              const x = c % B.rong;
              for (const n of [
                x > 0 ? c - 1 : -1,
                x < B.rong - 1 ? c + 1 : -1,
                c - B.rong,
                c + B.rong,
              ]) {
                const j = own.get(n);
                if (n >= 0 && j !== undefined && j !== i) nb.add(j);
              }
            }
            // Ưu tiên số liệu chính game tính (theo từng ô chạm nhau, có xét chênh phẩm); thiếu thì dùng cách ước lượng theo hệ cả món.
            const gm = R && R.manh && R.manh[i];
            if (gm && typeof gm.generators === "number") {
              f.sinh += gm.generators - 0.5 * (gm.weakGenerators || 0);
              f.khac += gm.restrainers || 0;
            } else
              for (const j of nb) {
                if (!thong(j)) continue;
                let sinh = 0,
                  khac = 0;
                for (const a of hes[j])
                  for (const b of hes[i]) {
                    const d = heTacDong(a, b);
                    if (d > 0) sinh = 1;
                    else if (d < 0) khac = 1;
                  }
                f.sinh += sinh;
                f.khac += khac;
              }
            for (const c of p.cells) {
              const m = B.mau[c];
              if (m && m !== "vo_sac" && hes[i].length) {
                const w = Math.max(...hes[i].map((h) => oHop(m, h)));
                f.hop += w;
                if (!w) {
                  if (hes[i].some((h) => oKhac(m, h))) f.lech++;
                  else f.trungTinh++;
                }
              }
            }
            {
              let k = 0;
              for (const c of p.cells) if (B.hy.has(c)) k++;
              if (k) f.huyet += 1 + 0.125 * (k - 1);
            }
            // 6.19: ba tầng theo linh căn: trùng hệ linh căn > dị linh căn cùng gốc > hệ không bị linh căn khắc (trung tính); hệ bị linh căn khắc bị trừ nhẹ.
            if (hes[i].some((h) => B.lc.has(h))) f.lc++;
            else if (hes[i].some((h) => B.lcRoot.has(gocHe(h)))) f.lcGoc++;
            else if (
              hes[i].length &&
              hes[i].every((h) => [...B.lc].some((l) => oKhac(l, h)))
            )
              f.lcKhac++;
            // Hướng build: chỉ tính món ĐANG THÔNG và đúng lưu phái / hệ của hướng; món đó nằm trên huyệt được cộng thêm.
            if (B.build) {
              const itB = B.items.get(p.m.item);
              if (itB && buildMatch(B.build, itB)) {
                f.build++;
                for (const c of p.cells) if (B.hy.has(c)) f.bhuyet++;
              }
            }
          });
          return f;
        }
        function biasScore(B, manh, R) {
          if (!B) return 0;
          try {
            const f = biasInfo(B, manh, R);
            let s = 0;
            if (B.dir === "tien") s += 8 * f.sinh - 10 * f.khac;
            else if (B.dir === "ma") s += 8 * f.khac - 3 * f.sinh;
            if (B.prio)
              s +=
                2 * f.hop -
                1.5 * f.lech +
                4 * f.lc +
                2.4 * f.lcGoc -
                1.5 * f.lcKhac +
                5 * f.huyet;
            if (B.build) s += 12 * f.build + 4 * f.bhuyet;
            return s * (S.biasK || 1);
          } catch (e) {
            return 0;
          }
        }
        const DIR_TEN = {
          "": "Theo Hệ Số Game",
          tien: "Tiên Tu · Tương Sinh",
          ma: "Ma Tu · Tương Khắc",
        };
        function biasSummary(nv, best) {
          if (!S.dir && !S.prio && !S.kmBuild) return "";
          try {
            const K = S.core,
              c = C(),
              nv2 = clone(nv);
            nv2.kinhMach.manh = best.manh;
            const g = K.luoiKinhMach(c, nv2),
              B = biasCtx(nv2, g);
            const manh = best.manh.map((m) => ({
              m,
              cells: K.oCuaManh(g, m, c.items.get(m.item)) || [],
            }));
            const f = biasInfo(B, manh, best.R);
            return `<div class="vk-mu" style="font-size:12px;margin-top:6px">Hướng xếp: <b>${DIR_TEN[S.dir || ""]}</b>${S.prio ? " · ưu tiên linh căn &amp; huyệt" : ""}${B.build ? " · Hướng Build: <b>" + esc(B.build.ten) + "</b> (" + f.build + " món đúng hướng đang thông, " + f.bhuyet + " ô của chúng nằm trên huyệt)" : ""}. Đường nối tương sinh: ${f.sinh} · tương khắc: ${f.khac} · ô hợp màu: ${num(f.hop, 1)} · ô đặt lên huyệt: ${f.huyet} · món cùng hệ linh căn: ${f.lc}.</div>`;
          } catch (e) {
            return "";
          }
        }

        // ═════ BẢN 6.19: TRẦN PHÁP LỰC · PHẨM BẰNG CẢNH GIỚI ═════
        /* Luật game (đọc từ code): uy lực chiêu của món nhân thêm min(1, trần pháp lực của món / pháp lực của người chơi).
     Trần của món = pháp lực ở đầu cảnh giới kế tiếp của phẩm đó; Nghịch Thiên không có trần. Món chưa chạm trần giữ nguyên uy lực;
     "phẩm bằng cảnh giới" là món có trần đúng bằng pháp lực đầu cảnh giới kế của người chơi (vừa sức, dùng được lâu nhất trước khi chạm trần). */
        const CAP_W = 14; // trừ cho mỗi chiêu bị kẹp hẳn (1 trận mẫu thắng thêm ≈ 11 điểm); kẹp một phần trừ theo tỉ lệ
        const TIER_W = 2.5; // cộng cho mỗi món đang thông mà phẩm bằng cảnh giới
        function capCtxOf(nv) {
          const K = S.core;
          if (!K || !K.skillCap || !K.spellPower) return null;
          try {
            const base = K.spellPower(nv.canhGioi, nv.tieuCanhGioi || 0),
              next = K.spellPower(nv.canhGioi + 1, 0);
            return base > 0 ? { K, base, next } : null;
          } catch (e) {
            return null;
          }
        }
        function capUp(X, it) {
          try {
            const hb = X.K.skillCap(it);
            return !(hb > 0) || hb === Infinity ? 1 : Math.min(1, hb / X.base);
          } catch (e) {
            return 1;
          }
        }
        function capTierMatch(X, it) {
          try {
            const hb = X.K.skillCap(it);
            return (
              Number.isFinite(hb) &&
              Number.isFinite(X.next) &&
              Math.abs(hb - X.next) < 1e-6 * Math.max(1, X.next)
            );
          } catch (e) {
            return false;
          }
        }
        function capScore(X, R) {
          if (!X || !R || !R.manh) return 0;
          let s = 0;
          for (const m of R.manh) {
            if (!m || !m.thong || !m.item) continue;
            if (m.item.chieu) s -= CAP_W * (1 - capUp(X, m.item));
            if (capTierMatch(X, m.item)) s += TIER_W;
          }
          return s;
        }

        function kmItemPower(it) {
          if (!it) return 0;
          let p = 0;
          const ph = it.pham_cap || 1;
          p += ph * 8;
          if (it.chieu) {
            const ch = it.chieu;
            const dmgW =
              ch.dang === "cong" ? 30 : ch.dang === "khong_che" ? 22 : 16;
            p += (ch.uy || 0) * dmgW;
            p += (ch.effects || []).length * 8;
          }
          const bd = it.bi_dong || {};
          p += (bd.toc_do || 0) * 100;
          p += (bd.dot_pha || 0) * 80;
          p += (bd.khi_huyet || 0) * 40;
          p += Math.min(0.3, bd.ho_the || 0) * 35;
          if (it.linh_luc) p += it.linh_luc * 10;
          return p;
        }

        function makeEval(nv0, enemies, mode) {
          nv0 = lnPrep(nv0);
          const K = S.core,
            c = C(),
            cache = new Map();
          const g0 = K.luoiKinhMach(c, nv0),
            hy0 = hySet(g0, nv0.kinhMach),
            B = biasCtx(nv0, g0),
            capX = capCtxOf(nv0),
            ngW = S.dir === "ma" ? 0.4 : 1,
            maxHoThe =
              0.6 +
              ((nv0.theChat &&
                nv0.theChat.dac_tinh &&
                nv0.theChat.dac_tinh.ho_the_tran) ||
                0);
          return (manh) => {
            const key = manh
              .map((p) => p.key)
              .sort()
              .join("|");
            if (cache.has(key)) return cache.get(key);
            const nv = clone(nv0);
            nv.kinhMach.manh = manh.map((p) => ({ ...p.m }));
            const R = K.tinhKinhMach(nv, c),
              P = K.taoBenTa(nv, c);
            let fightScore = 0,
              wins = 0;
            for (const { E } of enemies) {
              const r = fight(P, E);
              const hpLeft = r.khiHuyetThapNhat / P.khiHuyetToiDa;
              const dealt = Math.min(
                1,
                ((r.stTa || 0) * Math.max(1, r.nHiep)) / E.khiHuyetToiDa,
              );
              if (r.thang) {
                wins++;
                fightScore +=
                  mode === "danh"
                    ? 100 + 15 * hpLeft + 60 / Math.max(1, r.nHiep)
                    : 100 + 50 * hpLeft + 25 / Math.max(1, r.nHiep);
              } else fightScore += 50 * dealt;
            }
            const thong = R.manh.filter((m) => m && m.thong).length;
            const toc = R.biDong.toc_do || 0,
              dp = R.biDong.dot_pha || 0;
            const ng = (R.diemNghich || 0) * ngW;
            // Linh lực: hồi mỗi lượt phải đủ ra chiêu; món không thông chỉ chiếm chỗ.
            const ll = P.linhLucMoiLuot || 0;
            const atk = (P.chieu || [])
              .filter((x) => x.dang && x.phi > 0)
              .map((x) => x.phi);
            const minCost = atk.length ? Math.min(...atk) : 0;
            const dead = R.manh.filter((m) => m && !m.thong).length;
            const llScore =
              (mode === "tu" ? 1 : mode === "danh" ? 5 : 4) * ll -
              (minCost && ll < minCost ? 30 : 0) -
              8 * dead;

            // 7.11.1: Tối ưu huyệt đạo: tận dụng tối đa ô huyệt để buff mảnh chủ lực
            let hyScore = 0;
            const usedCells = new Set();
            manh.forEach((p, idx) => {
              p.cells.forEach((x) => usedCells.add(x));
              const q = p.cells.filter((x) => hy0.has(x)).length;
              if (q > 0) {
                const rm = R.manh && R.manh[idx];
                if (rm && rm.thong) {
                  const it = c.items.get(p.m.item);
                  const pwr = kmItemPower(it);
                  hyScore += 25 * q + 0.3 * pwr * q;
                } else {
                  hyScore -= 40 * q; // chiếm huyệt mà không thông: phạt nặng
                }
              }
            });
            for (const h of hy0) {
              if (
                g0.vung[h] >= 0 &&
                nv0.kinhMach.trangThai[h] === "thong" &&
                !usedCells.has(h)
              ) {
                hyScore -= 35; // ô huyệt mở được mà bị bỏ trống
              }
            }

            // 7.11.1: Khống chế hộ thể: game chỉ lấy tối đa 60% (HO_THE_MAX)
            const curHoThe = (R.biDong && R.biDong.ho_the) || 0;
            let hoThePenalty = 0;
            if (curHoThe > maxHoThe) {
              const excess = curHoThe - maxHoThe;
              hoThePenalty =
                200 * excess + (excess > 0.08 ? 350 * (excess - 0.08) : 0);
            }

            let s;
            // Điểm nghịch: mỗi điểm −3% tỉ lệ đột phá (tối đa −15%), thêm phản phệ trong trận (trận mẫu đã tính).
            if (mode === "tu")
              s =
                0.3 * fightScore +
                400 * toc +
                300 * dp +
                thong -
                40 * ng +
                llScore;
            else if (mode === "danh")
              s = fightScore + 0.2 * thong - 3 * ng + llScore;
            else
              s =
                fightScore +
                30 * toc +
                20 * dp +
                0.2 * thong -
                10 * ng +
                llScore;
            s += hyScore - hoThePenalty;
            s += biasScore(B, manh, R) + capScore(capX, R);
            if (S.hbRatio) s -= hbRatioPenalty(manh, R);
            // Xếp Full Ô: thưởng lớn theo số ô được phủ để bộ tìm kiếm ưu tiên lấp đầy lưới.
            if (S.full) s += 20 * manh.reduce((a, p) => a + p.cells.length, 0);
            const out = { s, wins, P, R };
            cache.set(key, out);
            return out;
          };
        }

        function buildCandidates(nv0) {
          const K = S.core,
            c = C();
          const pool = Object.keys(nv0.tuiDo).filter((id) => {
            const it = c.items.get(id);
            return (
              it &&
              (it.loai === "cong_phap" || it.loai === "phap_khi") &&
              it.hinh &&
              (it.canh_gioi ?? 0) <= nv0.canhGioi
            );
          });
          const g = K.luoiKinhMach(c, nv0),
            cand = {};
          for (const id of pool) {
            const it = c.items.get(id),
              seen = new Set();
            cand[id] = [];
            for (let xoay = 0; xoay < 4; xoay++)
              for (let y = 0; y < g.cao; y++)
                for (let x = 0; x < g.rong; x++) {
                  const m = { item: id, x, y, xoay };
                  let err;
                  try {
                    err = K.kiemTraDat(nv0, c, m);
                  } catch (e) {
                    err = "x";
                  }
                  if (err) continue;
                  const cells = K.oCuaManh(g, m, it);
                  if (!cells) continue;
                  const key =
                    id + ":" + [...cells].sort((a, b) => a - b).join(",");
                  if (seen.has(key)) continue;
                  seen.add(key);
                  cand[id].push({ m, cells, key });
                }
          }
          return { cand, g };
        }

        // Xếp tham lam nhanh (giống nút tự đặt của game): lần lượt đặt món + vị trí làm tăng điểm nhiều nhất.
        async function greedy(nv0, mode) {
          nv0 = lnPrep(nv0);
          const K = S.core,
            c = C(),
            { cand, g } = buildCandidates(nv0),
            B = biasCtx(nv0, g),
            hy0 = hySet(g, nv0.kinhMach),
            maxHoThe =
              0.6 +
              ((nv0.theChat &&
                nv0.theChat.dac_tinh &&
                nv0.theChat.dac_tinh.ho_the_tran) ||
                0);
          if (S.hbLite)
            for (const id of Object.keys(cand)) {
              const a = cand[id];
              if (a.length > 80) {
                const sp = Math.ceil(a.length / 80);
                cand[id] = a.filter((_, i) => i % sp === 0);
              }
            }
          const capX = capCtxOf(nv0);
          const quick = (manh) => {
            const nv = clone(nv0);
            nv.kinhMach.manh = manh.map((p) => ({ ...p.m }));
            const R = K.tinhKinhMach(nv, c);
            const uy = (R.chieu || []).reduce(
              (a, x) => a + (x.uyLuc || x.uy || 0) / 10,
              0,
            );
            const toc = R.biDong.toc_do || 0,
              dp = R.biDong.dot_pha || 0;
            const w =
              mode === "tu"
                ? [0.5, 60, 40, 0.3]
                : mode === "danh"
                  ? [1.5, 3, 2, 1.2]
                  : [1, 12, 8, 1];
            const thongAll = R.manh.every((m) => !m || m.thong);

            // 7.11.1: Huyệt & Hộ Thể trong quick
            let hyScore = 0;
            const usedCells = new Set();
            manh.forEach((p, idx) => {
              p.cells.forEach((x) => usedCells.add(x));
              const q = p.cells.filter((x) => hy0.has(x)).length;
              if (q > 0) {
                const rm = R.manh && R.manh[idx];
                if (rm && rm.thong) {
                  const it = c.items.get(p.m.item);
                  hyScore += 18 * q + 0.2 * kmItemPower(it) * q;
                } else {
                  hyScore -= 25 * q;
                }
              }
            });
            for (const h of hy0) {
              if (
                g.vung[h] >= 0 &&
                nv0.kinhMach.trangThai[h] === "thong" &&
                !usedCells.has(h)
              ) {
                hyScore -= 20;
              }
            }
            const curHoThe = (R.biDong && R.biDong.ho_the) || 0;
            const hoThePenalty =
              curHoThe > maxHoThe ? 140 * (curHoThe - maxHoThe) : 0;

            return (
              w[0] * R.linhLuc +
              w[1] * toc +
              w[2] * dp +
              w[3] * uy +
              hyScore -
              hoThePenalty -
              6 * (R.diemNghich || 0) * (S.dir === "ma" ? 0.4 : 1) +
              biasScore(B, manh, R) +
              capScore(capX, R) +
              (S.full ? 3 * manh.reduce((a, p) => a + p.cells.length, 0) : 0) -
              (thongAll || S.full ? 0 : 1000)
            );
          };
          let cur = [],
            curS = quick(cur);
          for (let round = 0; round < 40; round++) {
            let best = null;
            const used = new Set(cur.flatMap((p) => p.cells));
            for (const id of Object.keys(cand)) {
              if (cur.some((p) => p.m.item === id)) continue;
              for (const cnd of cand[id]) {
                if (cnd.cells.some((x) => used.has(x))) continue;
                const v = quick([...cur, cnd]);
                if (!best || v > best.v) best = { v, cnd };
              }
            }
            if (!best || best.v <= curS + 1e-9) break;
            cur.push(best.cnd);
            curS = best.v;
            if (round % 3 === 0) await sleep0();
          }
          return cur.map((p) => ({ ...p.m }));
        }

        async function anneal({
          nv0,
          mode,
          iters,
          init,
          onProg,
          label,
          seed: seed0,
          customEval,
        }) {
          const enemies = benchEnemies(nv0.canhGioi, nv0.tieuCanhGioi || 0);
          const ev = customEval || makeEval(nv0, enemies, mode);
          const { cand, g } = buildCandidates(nv0);
          const ids = Object.keys(cand).filter((k) => cand[k].length);
          const hy0 = hySet(g, nv0.kinhMach);
          const hyOf = (cn) => cn.cells.filter((x) => hy0.has(x)).length;
          let seed = seed0 || 12345;
          const rnd = () => {
            seed = (seed * 1103515245 + 12345) % 2147483648;
            return seed / 2147483648;
          };
          const overlaps = (manh, c, skip = -1) => {
            const used = new Set();
            manh.forEach((p, i) => {
              if (i !== skip) p.cells.forEach((x) => used.add(x));
            });
            return c.cells.some((x) => used.has(x));
          };
          // 6.19: đề xuất chỗ đặt thông minh: một nửa số lần chọn ngẫu nhiên thuần, nửa còn lại chọn tốt nhất trong 4 chỗ ngẫu nhiên theo (độ hợp màu ô) + (chạm đan điền / món đã đặt, để dễ thông).
          const mauK = (nv0.kinhMach && nv0.kinhMach.mau) || [],
            itemsK = C().items;
          const affOf = (cn) => {
            if (cn.aff !== undefined) return cn.aff;
            const it = itemsK.get(cn.m.item),
              hs = ((it && it.he) || []).filter((h) => h && h !== "vo_sac");
            let a = 0,
              n = 0;
            for (const x of cn.cells) {
              const m = mauK[x];
              if (m && m !== "vo_sac" && hs.length) {
                a += Math.max(...hs.map((h) => oHop(m, h)));
                n++;
              }
            }
            return (cn.aff = n ? a / n : 0.4);
          };
          const nearOf = (cn, used) =>
            cn.cells.some((x) => {
              const cx = x % g.rong;
              return [
                cx > 0 ? x - 1 : -1,
                cx < g.rong - 1 ? x + 1 : -1,
                x - g.rong,
                x + g.rong,
              ].some((n) => n >= 0 && (n === g.danDien || used.has(n)));
            });
          const smart = (id, next) => {
            const arr = cand[id];
            if (rnd() < 0.4) return arr[Math.floor(rnd() * arr.length)];
            const used = new Set();
            next.forEach((p) => p.cells.forEach((x) => used.add(x)));
            const itSmart = itemsK.get(id);
            const isHighVal =
              itSmart && (itSmart.chieu || (itSmart.pham_cap || 1) >= 4);
            let best = null,
              bs = -1e9;
            for (let k = 0; k < 5; k++) {
              const c = arr[Math.floor(rnd() * arr.length)];
              const hyCount = hyOf(c);
              const hyPref =
                hyCount > 0 ? (isHighVal ? 1.8 * hyCount : 0.4 * hyCount) : 0;
              const sc =
                affOf(c) + (nearOf(c, used) ? 0.6 : 0) + hyPref + 0.1 * rnd();
              if (sc > bs) {
                bs = sc;
                best = c;
              }
            }
            return best;
          };
          let cur = [];
          if (init)
            for (const m of init) {
              const c = (cand[m.item] || []).find(
                (c) => c.m.x === m.x && c.m.y === m.y && c.m.xoay === m.xoay,
              );
              if (c && !overlaps(cur, c)) cur.push(c);
            }
          let curS = ev(cur).s,
            best = cur,
            bestS = curS;
          const T0 = init && init.length ? 10 : 40;
          for (let it = 0; it < iters; it++) {
            if (S.abort || S.kmAbort) break;
            if (it % 20 === 0) {
              onProg && onProg(it / iters, label);
              await sleep0();
            }
            const T = Math.max(0.4, T0 * (1 - it / iters));
            const next = cur.slice();
            const r = rnd();
            const free = () =>
              ids.filter((id) => !next.some((p) => p.m.item === id));
            if (r < 0.3 || next.length === 0) {
              const f = free();
              if (!f.length) continue;
              const id = f[Math.floor(rnd() * f.length)];
              const c = smart(id, next);
              if (overlaps(next, c)) continue;
              next.push(c);
            } else if (r < 0.4) next.splice(Math.floor(rnd() * next.length), 1);
            else if (r < 0.7) {
              // nhích món sang vị trí / hướng xoay lân cận (giữ nguyên món, đổi quan hệ kề cạnh)
              const i = Math.floor(rnd() * next.length),
                c0 = next[i];
              const nb = cand[c0.m.item].filter(
                (c) =>
                  c !== c0 &&
                  Math.abs(c.m.x - c0.m.x) <= 2 &&
                  Math.abs(c.m.y - c0.m.y) <= 2,
              );
              if (!nb.length) continue;
              const c = nb[Math.floor(rnd() * nb.length)];
              if (overlaps(next, c, i)) continue;
              next[i] = c;
            } else if (r < 0.9) {
              const i = Math.floor(rnd() * next.length);
              const id = next[i].m.item;
              const c = smart(id, next);
              if (overlaps(next, c, i)) continue;
              next[i] = c;
            } else {
              const i = Math.floor(rnd() * next.length);
              const f = free();
              if (!f.length) continue;
              const id = f[Math.floor(rnd() * f.length)];
              const c = smart(id, next);
              if (overlaps(next, c, i)) continue;
              next[i] = c;
            }
            const e = ev(next);
            if (e.s >= curS || rnd() < Math.exp((e.s - curS) / T)) {
              cur = next;
              curS = e.s;
              if (e.s > bestS) {
                best = next;
                bestS = e.s;
              }
            }
          }
          const e = ev(best);
          return {
            manh: best.map((p) => ({ ...p.m })),
            score: e.s,
            wins: e.wins,
            n: enemies.length,
            P: e.P,
            R: e.R,
          };
        }

        // Tinh chỉnh cuối (leo đồi): thử nhích từng món, thêm món kề cạnh, thay món, bỏ món — chỉ nhận khi điểm tăng; lặp đến khi hết cải thiện.
        async function polish(nv0, mode, res, onProg, customEval) {
          const enemies = benchEnemies(nv0.canhGioi, nv0.tieuCanhGioi || 0),
            ev = customEval || makeEval(nv0, enemies, mode);
          const { cand, g } = buildCandidates(nv0),
            ids = Object.keys(cand).filter((k) => cand[k].length);
          let seed = 777;
          const rnd = () => {
            seed = (seed * 1103515245 + 12345) % 2147483648;
            return seed / 2147483648;
          };
          const toP = (m) =>
            (cand[m.item] || []).find(
              (c) => c.m.x === m.x && c.m.y === m.y && c.m.xoay === m.xoay,
            );
          const overl = (arr, cn, skip = -1) => {
            const used = new Set();
            arr.forEach((p, i) => {
              if (i !== skip) p.cells.forEach((x) => used.add(x));
            });
            return cn.cells.some((x) => used.has(x));
          };
          let cur = res.manh.map(toP).filter(Boolean),
            curS = ev(cur).s;
          const t0 = Date.now(),
            over = () => Date.now() - t0 > 30000 || S.abort || S.kmAbort;
          const sample = (arr, n) => {
            if (arr.length <= n) return arr;
            const out = [];
            for (let k = 0; k < n; k++)
              out.push(arr[Math.floor(rnd() * arr.length)]);
            return out;
          };
          for (let round = 0; round < 5 && !over(); round++) {
            let improved = false;
            onProg && onProg(round / 5);
            for (let i = 0; i < cur.length && !over(); i++) {
              // nhích
              for (const cn of cand[cur[i].m.item]) {
                if (
                  cn === cur[i] ||
                  Math.abs(cn.m.x - cur[i].m.x) > 3 ||
                  Math.abs(cn.m.y - cur[i].m.y) > 3 ||
                  overl(cur, cn, i)
                )
                  continue;
                const nx = cur.slice();
                nx[i] = cn;
                const e = ev(nx);
                if (e.s > curS + 1e-9) {
                  cur = nx;
                  curS = e.s;
                  improved = true;
                }
              }
              await sleep0();
            }
            const used = new Set();
            cur.forEach((p) => p.cells.forEach((x) => used.add(x)));
            const adj = (cn) =>
              cn.cells.some((x) => {
                const cx = x % g.rong;
                return [
                  cx > 0 ? x - 1 : -1,
                  cx < g.rong - 1 ? x + 1 : -1,
                  x - g.rong,
                  x + g.rong,
                ].some((n) => n >= 0 && used.has(n));
              });
            for (const id of ids) {
              // thêm món chưa dùng, ưu tiên chỗ kề các món đã xếp
              if (over()) break;
              if (cur.some((p) => p.m.item === id)) continue;
              let best = null;
              for (const cn of sample(
                cand[id].filter((c) => !overl(cur, c) && adj(c)),
                20,
              )) {
                const e = ev([...cur, cn]);
                if (e.s > curS + 1e-9 && (!best || e.s > best.s))
                  best = { s: e.s, cn };
              }
              if (best) {
                cur = [...cur, best.cn];
                curS = best.s;
                improved = true;
                best.cn.cells.forEach((x) => used.add(x));
              }
              await sleep0();
            }
            for (let i = 0; i < cur.length && !over(); i++) {
              // thay bằng món khác chiếm cùng vùng
              const area = new Set(cur[i].cells);
              let best = null;
              for (const id of ids) {
                if (cur.some((p) => p.m.item === id)) continue;
                for (const cn of sample(
                  cand[id].filter(
                    (c) =>
                      c.cells.some((x) => area.has(x)) && !overl(cur, c, i),
                  ),
                  6,
                )) {
                  const nx = cur.slice();
                  nx[i] = cn;
                  const e = ev(nx);
                  if (e.s > curS + 1e-9 && (!best || e.s > best.s))
                    best = { s: e.s, nx };
                }
              }
              if (best) {
                cur = best.nx;
                curS = best.s;
                improved = true;
              }
              await sleep0();
            }
            for (let i = cur.length - 1; i >= 0; i--) {
              const nx = cur.filter((_, j) => j !== i),
                e = ev(nx);
              if (e.s > curS + 1e-9) {
                cur = nx;
                curS = e.s;
                improved = true;
              }
            } // bỏ món gây hại
            if (!improved) break;
          }
          const e = ev(cur);
          return {
            manh: cur.map((p) => ({ ...p.m })),
            score: e.s,
            wins: e.wins,
            n: enemies.length,
            P: e.P,
            R: e.R,
          };
        }

        // Bỏ khỏi cách xếp mọi món không thông (không có tác dụng gì), rồi chấm lại.
        // Xếp Full Ô: sau khi tìm xong, nhét thêm mọi món còn trong túi vào các ô còn trống (ưu tiên món phủ nhiều ô nhất).
        function fillRest(nv, res, mode) {
          const K = S.core,
            c = C(),
            nv0 = clone(nv);
          nv0.kinhMach.manh = [];
          const { cand, g } = buildCandidates(nv0);
          const manh = res.manh.map((m) => ({ ...m }));
          const used = new Set();
          manh.forEach((m) =>
            (K.oCuaManh(g, m, c.items.get(m.item)) || []).forEach((x) =>
              used.add(x),
            ),
          );
          for (let guard = 0; guard < 60; guard++) {
            let best = null;
            for (const id of Object.keys(cand)) {
              if (manh.some((m) => m.item === id)) continue;
              for (const cn of cand[id]) {
                if (cn.cells.some((x) => used.has(x))) continue;
                if (!best || cn.cells.length > best.cells.length) best = cn;
              }
            }
            if (!best) break;
            manh.push({ ...best.m });
            best.cells.forEach((x) => used.add(x));
          }
          if (manh.length === res.manh.length) return res;
          const nv3 = clone(nv);
          nv3.kinhMach.manh = manh;
          return { ...evalCurrent(nv3, mode), manh };
        }
        // Thống kê độ phủ lưới: số ô đã phủ / số ô có thể phủ bằng các món đang có trong túi.
        function coverNote(nv, best) {
          try {
            const K = S.core,
              c = C(),
              nv0 = clone(nv);
            nv0.kinhMach.manh = [];
            const { cand, g } = buildCandidates(nv0),
              tot = new Set();
            for (const id of Object.keys(cand))
              for (const cn of cand[id]) cn.cells.forEach((x) => tot.add(x));
            const used = new Set();
            best.manh.forEach((m) =>
              (K.oCuaManh(g, m, c.items.get(m.item)) || []).forEach((x) =>
                used.add(x),
              ),
            );
            for (const x of used) tot.add(x);
            return `<div class="vk-mu" style="font-size:12px;margin-top:6px">Độ phủ lưới: <b>${used.size}/${tot.size}</b> ô${used.size < tot.size ? " (túi chưa đủ món vừa hình để lấp hết ô còn lại)" : " · đã lấp đầy"}.</div>`;
          } catch (e) {
            return "";
          }
        }
        function stripDead(nv, res, mode) {
          if (S.full) return fillRest(nv, res, mode);
          let manh = res.manh.slice();
          for (let k = 0; k < 5; k++) {
            const nv2 = clone(nv);
            nv2.kinhMach.manh = manh;
            const R = S.core.tinhKinhMach(nv2, C());
            const keep = manh.filter((m, i) => R.manh[i] && R.manh[i].thong);
            if (keep.length === manh.length) break;
            manh = keep;
          }
          if (manh.length === res.manh.length) return res;
          const nv3 = clone(nv);
          nv3.kinhMach.manh = manh;
          return { ...evalCurrent(nv3, mode), manh };
        }
        function evalCurrent(nv, mode) {
          const enemies = benchEnemies(nv.canhGioi, nv.tieuCanhGioi || 0);
          const ev = makeEval(
            { ...clone(nv), kinhMach: { ...clone(nv.kinhMach), manh: [] } },
            enemies,
            mode,
          );
          const Kc = S.core,
            Cc2 = C(),
            g2 = Kc.luoiKinhMach(Cc2, nv);
          const manh = nv.kinhMach.manh.map((m) => ({
            m,
            key: m.item + ":" + m.x + "," + m.y + "," + m.xoay,
            cells: Kc.oCuaManh(g2, m, Cc2.items.get(m.item)) || [],
          }));
          const e = ev(manh);
          return {
            manh: clone(nv.kinhMach.manh),
            score: e.s,
            wins: e.wins,
            n: enemies.length,
            P: e.P,
            R: e.R,
          };
        }

        // ───────────────────────── 5. Vẽ kinh mạch ─────────────────────────
        const BASE = {
          thuy: ["#3f6fb5", "#5a8fd6", "#2c5592", "#6f9fd0"],
          bang: ["#5fb8c9", "#86cfdc", "#3e9db0"],
          vo_sac: ["#7d7a76", "#9a958e", "#5f5c58"],
          hoa: ["#c0392b", "#d9622b", "#a8321f"],
          tho: ["#8a6a2e", "#a07a3a", "#6e5524"],
          kim: ["#c9a227", "#8f7a2a", "#e0b84a", "#a8892c", "#d4a017"],
          moc: ["#3f8f4a", "#5aa865", "#2f6f38"],
          loi: ["#7a4fb5", "#9a6fd0"],
          phong: ["#3fa08f", "#5cbfae"],
          am: ["#4a3a6a", "#5d4a82"],
        };
        const TINT = {
          thuy: "#cfdcef",
          bang: "#d3ecf0",
          vo_sac: "#dcd6cc",
          hoa: "#efc2b4",
          kim: "#f1e3b0",
          tho: "#e3d2b0",
          moc: "#cfe6c8",
          loi: "#d6c6f3",
          phong: "#cdebe5",
          am: "#d9d0e4",
        };

        // Chữ Hán của hệ trong game (CHn): hiện ở góc ô để khỏi nhầm các màu gần nhau (Lôi / Ám, Mộc / Phong, Thủy / Băng).
        const HE_HAN = {
          kim: "金",
          moc: "木",
          thuy: "水",
          hoa: "火",
          tho: "土",
          loi: "雷",
          bang: "冰",
          phong: "風",
          am: "暗",
          vo_sac: "無",
        };

        // Đường nối kinh lộ vẽ đúng như game (thành phần q6n): từ đan điền → tâm món thông đầu tiên → tâm món kế tiếp.
        // Mỗi món thông có R.manh[i].nguon = { manh: món nguồn (-1 = đan điền), tu: ô bên nguồn, den: ô bên món này }.
        // Tâm món = ô gần trọng tâm nhất (hàm SL); trong một món đường đi theo các ô kề nhau (BFS) từ tâm tới ô chạm.
        // cells[i] = ô của món i; isCP(i) = món i có phải tâm pháp / đấu pháp (chỉ loại này mới truyền mạch).
        function linkPaths(g, cells, R, isCP) {
          const nb = (i) => {
            const x = i % g.rong,
              y = Math.floor(i / g.rong),
              a = [];
            if (x > 0) a.push(i - 1);
            if (x < g.rong - 1) a.push(i + 1);
            if (y > 0) a.push(i - g.rong);
            if (y < g.cao - 1) a.push(i + g.rong);
            return a.filter((o) => g.vung[o] >= 0);
          };
          const anchor = (cs) => {
            const pts = cs.map((q) => [
              (q % g.rong) + 0.5,
              Math.floor(q / g.rong) + 0.5,
            ]);
            const mx = pts.reduce((a, p) => a + p[0], 0) / pts.length,
              my = pts.reduce((a, p) => a + p[1], 0) / pts.length;
            let b = 0,
              bd = Infinity;
            pts.forEach((p, k) => {
              const dd = (p[0] - mx) ** 2 + (p[1] - my) ** 2;
              if (dd < bd) {
                bd = dd;
                b = k;
              }
            });
            return cs[b];
          };
          const walk = (cs, from, to) => {
            const set = new Set(cs),
              prev = new Map([[from, -1]]),
              q = [from];
            while (q.length && !prev.has(to)) {
              const y = q.shift();
              for (const f of nb(y))
                if (set.has(f) && !prev.has(f)) {
                  prev.set(f, y);
                  q.push(f);
                }
            }
            if (!prev.has(to)) return [from, to];
            const out = [];
            for (let y = to; y >= 0; y = prev.get(y)) out.unshift(y);
            return out;
          };
          const rm = (i) => (R && R.manh && R.manh[i]) || null;
          const nguon = cells.map((_, i) => {
            const r = rm(i);
            return r && r.thong && r.nguon ? r.nguon : null;
          });
          if (!nguon.some(Boolean) && R && R.manh) {
            // Phòng hờ nếu game đổi tên trường nguon: dựng lại bằng BFS từ đan điền qua các món thông kề nhau (cùng thứ tự duyệt như game).
            const owner = new Map();
            cells.forEach((cs, i) => cs.forEach((q) => owner.set(q, i)));
            const touch = (L, I) => {
              for (const B of cells[I])
                for (const U of nb(B))
                  if (L < 0 ? U === g.danDien : owner.get(U) === L)
                    return { manh: L, tu: U, den: B };
              return null;
            };
            const th = (i) => !!(rm(i) && rm(i).thong && isCP(i));
            const q = [];
            cells.forEach((_, i) => {
              const t = th(i) && touch(-1, i);
              if (t) {
                nguon[i] = t;
                q.push(i);
              }
            });
            while (q.length) {
              const L = q.shift();
              cells.forEach((_, I) => {
                if (nguon[I] || !th(I)) return;
                const t = touch(L, I);
                if (t) {
                  nguon[I] = t;
                  q.push(I);
                }
              });
            }
          }
          const seen = new Set(),
            segs = [],
            dots = [];
          cells.forEach((cs, i) => {
            const ng = nguon[i];
            if (!ng || !cs.length) return;
            const p = anchor(cs),
              src =
                ng.manh >= 0 && cells[ng.manh] && cells[ng.manh].length
                  ? cells[ng.manh]
                  : null;
            const seq = [
              ...(src ? walk(src, anchor(src), ng.tu) : [g.danDien]),
              ...walk(cs, ng.den, p),
            ];
            for (let y = 1; y < seq.length; y++) {
              const a = seq[y - 1],
                b = seq[y],
                key = a < b ? a + "-" + b : b + "-" + a;
              if (!seen.has(key)) {
                seen.add(key);
                segs.push([a, b]);
              }
            }
            dots.push(p);
          });
          return { segs, dots };
        }

        function drawGrid(nv, manh, mark) {
          const K = S.core,
            c = C();
          const nv2 = clone(nv);
          nv2.kinhMach.manh = manh;
          const g = K.luoiKinhMach(c, nv2),
            km = nv2.kinhMach;
          const hy = hySet(g, km); // vị trí huyệt thật của kiếp này (huyetGoc + huyetThem), không phải huyệt gốc của khuôn
          const own = {},
            cols = [],
            used = {},
            pieces = [];
          const R = K.tinhKinhMach(nv2, c);
          manh.forEach((m, n) => {
            const it = c.items.get(m.item);
            const he = (it.he || ["vo_sac"])[0];
            const pal = BASE[he] || ["#888"];
            cols.push(pal[(used[he] = (used[he] || 0) + 1) % pal.length]);
            const cells = K.oCuaManh(g, m, it) || [];
            cells.forEach((x) => (own[x] = n));
            const rm = R.manh[n];
            pieces.push({
              it,
              cells,
              thong: rm ? rm.thong : false,
              heSo: rm ? rm.heSo : 0,
              onHuyet: cells.some((x) => hy.has(x)),
            });
          });
          const inGrid = (i) => g.vung[i] >= 0; // ô ngoài khuôn thể chất (dấu "." trong khuôn) không phải ô kinh mạch: không vẽ
          // chỉ vẽ vùng có ô mở (kèm một vòng ô ẩn viền quanh như game)
          let x0 = 99,
            y0 = 99,
            x1 = -1,
            y1 = -1;
          for (let i = 0; i < g.rong * g.cao; i++)
            if (
              inGrid(i) &&
              (km.trangThai[i] !== "an" || own[i] !== undefined)
            ) {
              const x = i % g.rong,
                y = Math.floor(i / g.rong);
              x0 = Math.min(x0, x);
              y0 = Math.min(y0, y);
              x1 = Math.max(x1, x);
              y1 = Math.max(y1, y);
            }
          if (x1 < 0) {
            x0 = x1 = g.danDien % g.rong;
            y0 = y1 = Math.floor(g.danDien / g.rong);
          }
          x0 = Math.max(0, x0 - 1);
          y0 = Math.max(0, y0 - 1);
          x1 = Math.min(g.rong - 1, x1 + 1);
          y1 = Math.min(g.cao - 1, y1 + 1);
          const Sz = 84,
            M = 10,
            W = (x1 - x0 + 1) * Sz + 2 * M,
            H = (y1 - y0 + 1) * Sz + 2 * M;
          const cx = (i) => i % g.rong,
            cy = (i) => Math.floor(i / g.rong);
          const ctr = (i) => [
            M + (cx(i) - x0 + 0.5) * Sz,
            M + (cy(i) - y0 + 0.5) * Sz,
          ];
          const cv = document.createElement("canvas");
          cv.width = W;
          cv.height = H;
          const d = cv.getContext("2d");
          d.fillStyle = "#f3ece0";
          d.fillRect(0, 0, W, H);
          for (let y = y0; y <= y1; y++)
            for (let x = x0; x <= x1; x++) {
              const i = y * g.rong + x;
              if (!inGrid(i)) continue;
              const px = M + (x - x0) * Sz,
                py = M + (y - y0) * Sz,
                st = km.trangThai[i];
              if (st === "an" && own[i] === undefined) {
                // ô chưa mở: khung đứt nét như game
                d.setLineDash([7, 6]);
                d.strokeStyle = "#cdc2b0";
                d.lineWidth = 2;
                d.strokeRect(px + 3, py + 3, Sz - 6, Sz - 6);
                d.setLineDash([]);
                if (hy.has(i)) {
                  d.beginPath();
                  d.arc(px + Sz - 16, py + 16, 9, 0, 7);
                  d.fillStyle = "#d9b228";
                  d.fill();
                  d.strokeStyle = "#7a5c00";
                  d.lineWidth = 1.5;
                  d.stroke();
                }
                continue;
              }
              let fill = TINT[km.mau[i]] || "#ddd";
              if (own[i] !== undefined) fill = cols[own[i]];
              d.fillStyle = fill;
              d.fillRect(px + 2, py + 2, Sz - 4, Sz - 4);
              d.strokeStyle = "#bdb2a3";
              d.lineWidth = 2;
              d.strokeRect(px + 2, py + 2, Sz - 4, Sz - 4);
              if (st === "ton") {
                // ô tổn: gạch chéo
                d.save();
                d.beginPath();
                d.rect(px + 2, py + 2, Sz - 4, Sz - 4);
                d.clip();
                d.strokeStyle = "rgba(168,70,20,.55)";
                d.lineWidth = 5;
                for (let k = -Sz; k < Sz * 2; k += 14) {
                  d.beginPath();
                  d.moveTo(px + k, py + Sz);
                  d.lineTo(px + k + Sz, py);
                  d.stroke();
                }
                d.restore();
              }
              if (st === "tac") {
                d.fillStyle = "#7a1f1a";
                d.font = "bold 38px sans-serif";
                d.textAlign = "center";
                d.textBaseline = "middle";
                d.fillText("×", px + Sz / 2, py + Sz / 2);
              }
              const hz = i === g.danDien ? "" : HE_HAN[km.mau[i]];
              if (hz) {
                d.font = "600 17px serif";
                d.textAlign = "left";
                d.textBaseline = "top";
                d.fillStyle =
                  own[i] !== undefined
                    ? "rgba(255,255,255,.8)"
                    : "rgba(30,21,18,.45)";
                d.fillText(hz, px + 7, py + 5);
              }
              if (i === g.danDien && own[i] === undefined) {
                d.fillStyle = "#fbf7ef";
                d.fillRect(px + 5, py + 5, Sz - 10, Sz - 10);
                d.strokeStyle = "#7a1f1a";
                d.lineWidth = 4;
                d.strokeRect(px + 5, py + 5, Sz - 10, Sz - 10);
                d.fillStyle = "#7a1f1a";
                d.font = "bold 40px serif";
                d.textAlign = "center";
                d.textBaseline = "middle";
                d.fillText("丹", px + Sz / 2, py + Sz / 2 + 2);
              }
              if (hy.has(i)) {
                d.beginPath();
                d.arc(px + Sz - 16, py + 16, 9, 0, 7);
                d.fillStyle = "#d9b228";
                d.fill();
                d.strokeStyle = "#7a5c00";
                d.lineWidth = 1.5;
                d.stroke();
              }
              if (mark && mark.has(i)) {
                d.strokeStyle = "#1a7f37";
                d.lineWidth = 7;
                d.strokeRect(px + 8, py + 8, Sz - 16, Sz - 16);
                d.fillStyle = "#1a7f37";
                d.font = "bold 18px sans-serif";
                d.textAlign = "left";
                d.textBaseline = "alphabetic";
                d.fillText("MỞ", px + 12, py + Sz - 12);
              }
            }
          // viền từng món
          pieces.forEach((p) => {
            const cs = new Set(p.cells);
            d.strokeStyle = "#1e1512";
            d.lineWidth = 7;
            for (const cI of cs) {
              const x = cI % g.rong,
                y = Math.floor(cI / g.rong),
                px = M + (x - x0) * Sz,
                py = M + (y - y0) * Sz;
              const L = (a, b, e, f) => {
                d.beginPath();
                d.moveTo(a, b);
                d.lineTo(e, f);
                d.stroke();
              };
              if (!cs.has(cI - g.rong)) L(px, py, px + Sz, py);
              if (!cs.has(cI + g.rong)) L(px, py + Sz, px + Sz, py + Sz);
              if (!cs.has(cI - 1) || x === 0) L(px, py, px, py + Sz);
              if (!cs.has(cI + 1) || x === g.rong - 1)
                L(px + Sz, py, px + Sz, py + Sz);
            }
          });
          // nối ô: đường kinh lộ như game (trắng, quầng xanh), chấm tròn ở tâm mỗi món thông
          try {
            const lk = linkPaths(
              g,
              pieces.map((p) => p.cells),
              R,
              (i) => pieces[i].it.loai === "cong_phap",
            );
            if (lk.segs.length) {
              const trace = () => {
                d.beginPath();
                lk.segs.forEach(([a, b]) => {
                  const A = ctr(a),
                    B = ctr(b);
                  d.moveTo(A[0], A[1]);
                  d.lineTo(B[0], B[1]);
                });
              };
              d.save();
              d.lineCap = "round";
              d.lineJoin = "round";
              [
                ["rgba(79,179,255,.30)", 0.36],
                ["rgba(143,214,255,.70)", 0.16],
                ["#ffffff", 0.06],
              ].forEach(([col, w]) => {
                trace();
                d.strokeStyle = col;
                d.lineWidth = Sz * w;
                d.stroke();
              });
              lk.dots.forEach((cI) => {
                const q = ctr(cI);
                d.beginPath();
                d.arc(q[0], q[1], Sz * 0.12, 0, 7);
                d.shadowColor = "#4fb3ff";
                d.shadowBlur = 14;
                d.fillStyle = "#fff";
                d.fill();
                d.shadowBlur = 0;
                d.lineWidth = 3;
                d.strokeStyle = "#7cc8ff";
                d.stroke();
              });
              d.restore();
            }
          } catch (e) {
            /* lỗi vẽ đường nối không được làm mất cả ảnh lưới */
          }
          // số thứ tự món: huy hiệu ở góc dưới trái ô đầu của món (không đè đường nối ở tâm món)
          pieces.forEach((p, n) => {
            if (!p.cells.length) return;
            const c0 = Math.min(...p.cells),
              px = M + (cx(c0) - x0) * Sz + 20,
              py = M + (cy(c0) - y0) * Sz + Sz - 20;
            d.beginPath();
            d.arc(px, py, 14, 0, 7);
            d.fillStyle = "#1e1512";
            d.fill();
            d.lineWidth = 2;
            d.strokeStyle = "#fff";
            d.stroke();
            d.font = "bold 17px sans-serif";
            d.textAlign = "center";
            d.textBaseline = "middle";
            d.fillStyle = "#fff";
            d.fillText(String(n + 1), px, py + 1);
          });
          const legend = pieces
            .map(
              (p, n) =>
                `<div class="vk-lg"><span class="vk-sw" style="background:${cols[n]}">${n + 1}</span><b>${esc(p.it.ten)}</b> <span class="vk-mu">· ${esc((p.it.he || ["vo_sac"]).map(heTen).join("/"))}${p.onHuyet ? " · trên huyệt" : ""}${p.thong ? "" : ' · <span class="vk-bad">không thông</span>'}</span></div>`,
            )
            .join("");
          return `<img class="vk-img" src="${cv.toDataURL("image/png")}" alt="kinh mạch"><div class="vk-note">Chấm vàng = huyệt (vị trí thật của kiếp này) · 丹 = đan điền · × = ô tắc · gạch chéo = ô tổn · chữ Hán ở góc ô = hệ linh căn của ô · đường sáng = mạch thông nối từ đan điền. Giữ tay lên ảnh để lưu.</div>${legend}`;
        }

        // ───────────────────────── 6. Gắn vào giao diện chung ─────────────────────────
        UI.refreshBtn.onclick = () => {
          S.best = null;
          S.cho = null;
          render();
        };

        const TABS = [
          ["tq", "Tổng Quan"],
          ["tkc", "Tàng Kinh Các"],
          ["dp", "Đột Phá & Thọ"],
          ["tr", "Trận"],
          ["tien", "Kiếm Linh Thạch"],
          ["cho", "Chợ Quanh Đây"],
          ["ld", "Luyện Đan"],
          ["cph", "Chế Phù"],
          ["lbo", "Luyện Bảo"],
          ["tph", "Trận Pháp"],
          ["tt", "Treo Thưởng"],
          ["db", "Dị Bảo"],
          ["san", "Đồ Nên Săn"],
          ["tcv", "Vật Phẩm"],
          ["tcq", "Quái Vật"],
          ["tcd", "Địa Danh"],
          ["bd", "Bản Đồ"],
        ];
        TABS.push(["bm", "Bản Mệnh Pháp Bảo"]);
        TABS.push(
          ["nlw", "Tổng Quan"],
          ["nlm", "Của Tôi"],
          ["nls", "Sinh Vật"],
          ["nlv", "Vật Phẩm"],
          ["nlc", "Cơ Duyên"],
        );
        TABS.push(
          ["atl", "Auto Tu Luyện"],
          ["atc", "Auto Tác Chiến"],
          ["asdb", "Auto Săn Dị Bảo"],
          ["asy", "Auto Săn Yêu"],
          ["abb", "Auto Buôn Bán"],
          ["akm", "Hướng Build"],
          ["bis", "Biệt Đội Late Game"],
          ["arr", "Auto Reroll Tư Chất"],
        );
        TABS.push(
          ["lhs", "Mở Khóa"],
          ["lht", "Thành Tựu"],
          ["lhd", "Dự Tính Điểm"],
          ["sv", "Lưu & Nạp Save"],
          ["tkb", "Thiên Kiêu Bảng"],
          ["nmn", "Nhân Mạch"],
        );
        const TNAME = Object.fromEntries(TABS);
        const GROUPS = [
          ["nv", "Nhân Vật", ["tq", "tkc", "bm"]],
          ["cd", "Đột Phá", ["dp", "tr"]],
          ["kl", "Kiếm Lời", ["tien", "cho", "ld", "cph", "lbo", "tph", "tt"]],
          ["tc", "Tra Cứu", ["db", "san", "tcv", "tcq", "tcd", "bd"]],
          ["nl", "Ngự Linh", ["nlw", "nlm", "nls", "nlv", "nlc"]],
          ["lh", "Luân Hồi", ["lhs", "lht", "lhd", "sv"]],
          ["nm", "Nhân Mạch", ["tkb", "nmn"]],
          [
            "au",
            "Tự Động",
            ["atl", "atc", "asdb", "asy", "abb", "akm", "bis", "arr"],
          ],
        ];
        const grpOf = (k) => GROUPS.find((g) => g[2].includes(k)) || GROUPS[0];
        S.tab = "tq";
        // Dựng lại thanh tab nhưng giữ nguyên vị trí vuốt (trước đây mỗi lần bấm tab là thanh nhảy về đầu) và cuộn nút đang chọn vào vùng nhìn thấy.
        function keepVisible(strip) {
          const b = strip.querySelector(".on");
          if (!b) return;
          const k = (UI.fit && UI.fit.k) || 1,
            r = b.getBoundingClientRect(),
            s = strip.getBoundingClientRect();
          if (!r.width || !s.width) return;
          if (r.left < s.left) strip.scrollLeft -= (s.left - r.left + 8) / k;
          else if (r.right > s.right)
            strip.scrollLeft += (r.right - s.right + 8) / k;
        }
        function drawTabs() {
          const g = grpOf(S.tab),
            gl = groupsEl.scrollLeft,
            tl = tabsEl.scrollLeft;
          const gh = GROUPS.map(
            (x) =>
              `<button data-g="${x[0]}" class="${x === g ? "on" : ""}">${x[1]}</button>`,
          ).join("");
          const th = g[2]
            .map(
              (k) =>
                `<button data-k="${k}" class="${k === S.tab ? "on" : ""}">${TNAME[k]}</button>`,
            )
            .join("");
          groupsEl.innerHTML = gh;
          tabsEl.innerHTML = th;
          groupsEl.scrollLeft = gl;
          if (S.tabGrp === g[0]) tabsEl.scrollLeft = tl;
          else tabsEl.scrollLeft = 0;
          S.tabGrp = g[0];
          keepVisible(groupsEl);
          keepVisible(tabsEl);
        }
        groupsEl.onclick = (e) => {
          const gk = e.target.dataset && e.target.dataset.g;
          const g = gk && GROUPS.find((x) => x[0] === gk);
          if (g) {
            S.abort = true;
            S.tab = g[2][0];
            render();
          }
        };
        tabsEl.onclick = (e) => {
          const k = e.target.dataset && e.target.dataset.k;
          if (k) {
            S.abort = true;
            S.tab = k;
            render();
          }
        };

        const errBox = (e) =>
          `<div class="vk-err"><b>Có lỗi:</b> ${esc((e && e.message) || e)}<br><span class="vk-mu" style="font-size:12px">Tool ${TOOL_VER}${S.core ? " · game " + esc(S.core.bundle) : ""}. Nếu lỗi lặp lại, chụp màn hình gửi Claude.</span></div>`;

        async function render() {
          if (S.tab === "km" || S.tab === "bld") S.tab = "akm"; // hai tab cũ đã gộp vào Hướng Build
          if (S.tab === "do") S.tab = "db"; // tab Dò Đồ Quý cũ đã quy về Dị Bảo
          drawTabs();
          body.onclick = null;
          try {
            if (S.tab === "tcv" || S.tab === "tcq") {
              S.abort = false;
              (S.tab === "tcv" ? tabVatPham : tabQuaiVat)();
              return;
            }
            if (S.tab === "arr") {
              S.abort = false;
              tabAutoReroll();
              return;
            }
            if (S.tab === "lhs") {
              S.abort = false;
              tabLuanHoi();
              return;
            } // Luân Hồi chạy được cả khi chưa vào kiếp nào
            if (S.tab === "lht") {
              S.abort = false;
              tabThanhTuu();
              return;
            }
            if (S.tab === "sv") {
              S.abort = false;
              tabLuuNapSave();
              return;
            } // Lưu & Nạp Save chạy được cả khi chưa vào kiếp nào
            if (!S.core) {
              const myTab = S.tab;
              body.innerHTML = `<div class="vk-card">⏳ <span id="vk-pg">Đang chuẩn bị…</span></div>`;
              // chỉ nạp code game MỘT lần dù người dùng bấm tab/làm mới liên tục trong lúc chờ (trước đây mỗi lần bấm nạp thêm một bản → nặng, đứng hình)
              if (!S.coreP)
                S.coreP = loadCore((m) => {
                  const el = body.querySelector("#vk-pg");
                  if (el) el.textContent = m;
                }).then(
                  (k) => {
                    S.core = k;
                    return k;
                  },
                  (e) => {
                    S.coreP = null;
                    throw e;
                  },
                );
              const wd = setTimeout(() => {
                const el = body.querySelector("#vk-pg");
                if (el && !S.core)
                  el.parentElement.insertAdjacentHTML(
                    "beforeend",
                    '<div class="vk-mu" style="font-size:12px;margin-top:6px">Đang lâu hơn bình thường. Nếu quá 30 giây, bấm ↻ để thử lại.</div>',
                  );
              }, 15000);
              try {
                await S.coreP;
              } finally {
                clearTimeout(wd);
              }
              if (S.tab !== myTab) return; // người dùng đã chuyển tab trong lúc chờ: lượt render của tab mới lo phần còn lại
            }
            if (!G().state.run) {
              body.innerHTML = `<div class="vk-card">Chưa có kiếp nào đang chơi. Vào game (tạo hoặc nạp kiếp) rồi bấm <b>Làm mới</b>.</div>`;
              return;
            }
            S.abort = false;
            if (S.core && S.core.sync) S.core.sync();
            ({
              tq: () => {
                tabTongQuan();
                tongQuanExtra();
              },
              sv: tabLuuNapSave,
              dp: tabDotPha2,
              tr: tabTran,
              tkc: tabTKC,
              bm: tabBanMenh,
              cho: tabCho,
              ld: tabLuyenDan,
              cph: tabCheePhu,
              lbo: tabLuyenBao,
              tph: tabTranPhap,
              tien: tabTien,
              bd: tabBanDo,
              tt: tabTreoThuong,
              db: tabDiBao,
              san: tabSan,
              tcv: tabVatPham,
              tcq: tabQuaiVat,
              tcd: tabDiaDanh,
              nlw: tabNLW,
              nlm: tabNLM,
              nls: tabNLS,
              nlv: tabNLV,
              nlc: tabNLC,
              lhd: tabDuTinhDiem,
              tkb: tabThienKieu,
              nmn: tabNhanMach,
              atl: tabAutoTuLuyen,
              atc: tabAutoTacChien,
              asdb: tabAutoSdb,
              abb: tabAutoBuon,
              asy: tabAutoSan,
              akm: tabAutoKm,
              bis: tabBis,
              arr: tabAutoReroll,
            })[S.tab]();
          } catch (e) {
            console.error(e);
            body.innerHTML =
              errBox(e) +
              '<button class="vk-btn sec" id="vk-retry">↻ Thử Lại</button>';
            const rb = body.querySelector("#vk-retry");
            if (rb)
              rb.onclick = () => {
                S.core = null;
                S.coreP = null;
                render();
              };
          }
        }

        const progressHtml = (id) =>
          `<div id="${id}" style="display:none"><div class="vk-bar"><i></i></div><div class="vk-mu" style="font-size:13px"></div><button class="vk-btn sec vk-stop">Dừng</button></div>`;
        function bindProgress(box) {
          box.style.display = "block";
          box.querySelector(".vk-stop").onclick = () => {
            S.abort = true;
          };
          return (f, label) => {
            box.querySelector("i").style.width = Math.round(f * 100) + "%";
            box.querySelector(".vk-mu").textContent =
              (label || "") + " " + Math.round(f * 100) + "%";
          };
        }

        // ── Tab Tổng quan
        function tabTongQuan() {
          const K = S.core,
            c = ctx(),
            run = c.run,
            nv = run.nhanVat;
          const tho = K.thoNguyenToiDa(nv);
          const lc = nv.linhCan
            ? `${{ thien: "Thiên", bien_di: "Biến dị", song: "Song", tap: "Tạp", vo: "Vô" }[nv.linhCan.pham] || nv.linhCan.pham} linh căn (${(nv.linhCan.he || []).map(heTen).join(", ")})`
            : "—";
          let sect = '<div class="vk-mu">Chưa vào tông môn.</div>';
          const tm = K.tongMonCua(c);
          if (tm) {
            let ten = tm.slot;
            try {
              ten = c.world.info(tm.slot).diaDanh.ten;
            } catch {}
            const reasons = K.thieuDeThangCap(c);
            const next = K.CAP_BAC[tm.capBac + 1];
            sect = `<div class="vk-row"><span>Tông môn</span><b>${esc(ten)}</b></div>
      <div class="vk-row"><span>Cấp bậc</span><b>${esc(K.CAP_BAC[tm.capBac])}</b></div>
      <div class="vk-row"><span>Công tích</span><b>${Math.floor(tm.congTich)}</b></div>
      ${next ? `<div class="vk-row"><span>Lên ${esc(next)}</span>${reasons.length ? `<span class="vk-bad">${esc(reasons.join("; "))}</span>` : '<span class="vk-ok">Đủ điều kiện xin khảo hạch — xem tab Trận</span>'}</div>` : ""}`;
          }
          const nghe =
            Object.entries(nv.nghe || {})
              .map(
                ([k, v]) =>
                  `${{ luyen_dan: "Luyện đan", che_phu: "Chế phù", luyen_bao: "Luyện bảo", tran_phap: "Trận pháp" }[k] || k}: bậc ${v.bac}, ${Math.floor(v.kinhNghiem)} kinh nghiệm`,
              )
              .join("<br>") || "—";
          // cơ duyên sắp hết hạn
          const seen = new Map();
          for (const l of run.log || [])
            if (l.expiresAt && l.key) seen.set(l.key, l);
          const dip =
            [...seen.values()]
              .filter((l) => l.expiresAt - run.nam >= 0.05)
              .sort((a, b) => a.expiresAt - b.expiresAt)
              .map(
                (l) =>
                  `<div class="vk-row"><span>${esc(
                    String(l.text)
                      .replace(/còn [\d.,]+ năm\.?/, "")
                      .replace(/[-]/g, ""),
                  )}</span><b>${num(l.expiresAt - run.nam)} năm</b></div>`,
              )
              .join("") || '<div class="vk-mu">Không có.</div>';
          body.innerHTML = `
    <div class="vk-card"><h3>${esc(nv.ten)}</h3>
      <div class="vk-row"><span>Cảnh giới</span><b>${esc(realmLabel(nv.canhGioi, nv.tieuCanhGioi))}</b></div>
      <div class="vk-row"><span>Tuổi / thọ</span><b>${Math.floor(nv.tuoi)} / ${tho} <span class="vk-mu">(còn ${Math.floor(tho - nv.tuoi)} năm)</span></b></div>
      <div class="vk-row"><span>Linh căn</span><b>${esc(lc)}</b></div>
      <div class="vk-row"><span>Thương thế</span><b>${nv.thuongThe ? `<span class="vk-bad">${nv.thuongThe} bậc</span>` : "Lành lặn"}</b></div>
      <div class="vk-row"><span>Lịch luyện</span><b>${num(nv.lichLuyen || 0)}${(nv.lichLuyen || 0) < 2 ? ' <span class="vk-bad">sắp cạn — đi đánh/đi xa để hồi</span>' : ""}</b></div>
      <div class="vk-row"><span>Linh thạch · Cống hiến</span><b>${Math.floor(nv.linhThach || 0)} · ${Math.floor(nv.congHien || 0)}</b></div>
      <div class="vk-row"><span>Nghề</span><b style="text-align:right">${nghe}</b></div>
      <div class="vk-row"><span>Lượt khai thông kinh mạch</span><b>${(nv.kinhMach.cho && nv.kinhMach.cho.mo) || 0}</b></div>
    </div>
    <div class="vk-card"><h3>Sư môn</h3>${sect}</div>
    <div class="vk-card"><h3>Cơ duyên sắp hết hạn</h3>${dip}</div>
    <div class="vk-card" style="border-left:3px solid #8b5cf6">
      <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:6px">
        <h3 style="margin:0;color:#a78bfa">💾 Lưu & Nạp Save (Tránh Thiên Đạo)</h3>
        <button class="vk-btn sec" id="tq-btn-to-sv" style="padding:3px 10px;font-size:12px;margin:0">Mở Tab Save ➜</button>
      </div>
      <div style="font-size:12px;color:var(--mut);margin-bottom:8px">
        Lưu điểm dự phòng nhanh trước khi Đột Phá / Giao Chiến, hoặc nạp file save mà không lo Thiên Đạo phạt.
      </div>
      <div style="display:flex;gap:6px;flex-wrap:wrap">
        <button class="vk-btn" id="tq-btn-quicksave" style="padding:5px 12px;font-size:12px;background:#3ddc97;color:#05140d">⚡ Quick Save Ngay</button>
        <button class="vk-btn sec" id="tq-btn-export" style="padding:5px 12px;font-size:12px">💾 Tải File Save (.txt)</button>
        <button class="vk-btn sec" id="tq-btn-cleantd" style="padding:5px 12px;font-size:12px" title="Xóa toàn bộ bộ nhớ theo dõi của Thiên Đạo">🧹 Tẩy Thiên Đạo</button>
      </div>
    </div>
    <div class="vk-card"><h3>Độ mạnh chung</h3><div id="vk-dm" class="vk-mu">Bấm để đánh thử với mọi loại quái cùng cảnh giới.</div><button class="vk-btn" id="vk-dmb">Đánh thử</button></div>
    <div class="vk-mu" style="font-size:12px;text-align:center">Tool ${TOOL_VER} · game ${esc(K.bundle)}</div>`;
          const tqToSv = body.querySelector("#tq-btn-to-sv");
          if (tqToSv) {
            tqToSv.onclick = () => {
              S.tab = "sv";
              render();
            };
          }
          const tqQs = body.querySelector("#tq-btn-quicksave");
          if (tqQs) {
            tqQs.onclick = () => {
              const note = prompt(
                "Nhập ghi chú cho bản lưu nhanh (hoặc để trống):",
                "",
              );
              if (note === null) return;
              const res = saveQuickSave(note);
              if (res.ok) {
                try {
                  UI.notify(res.msg);
                } catch (e) {}
              } else {
                alert("⚠️ " + res.msg);
              }
            };
          }
          const tqExp = body.querySelector("#tq-btn-export");
          if (tqExp) {
            tqExp.onclick = () => {
              const exp = doExportSave();
              if (exp.ok) {
                downloadSaveFile(exp.data, exp.fileName);
                try {
                  UI.notify("💾 Đã tải tệp save: " + exp.fileName);
                } catch (e) {}
              } else {
                alert("⚠️ " + exp.msg);
              }
            };
          }
          const tqClean = body.querySelector("#tq-btn-cleantd");
          if (tqClean) {
            tqClean.onclick = () => {
              cleanseThienDao();
              try {
                UI.notify("🧹 Đã thanh tẩy sạch sẽ mọi dấu vết Thiên Đạo!");
              } catch (e) {}
              alert(
                "🧹 Đã thanh tẩy thành công toàn bộ dữ liệu theo dõi của Thiên Đạo!",
              );
            };
          }
          body.querySelector("#vk-dmb").onclick = async (ev) => {
            ev.target.disabled = true;
            const out = body.querySelector("#vk-dm");
            out.textContent = "Đang đánh thử…";
            await sleep0();
            const P = K.taoBenTa(nvNow(), C());
            const res = [];
            for (const tc of [0, 1, 2, 3]) {
              let w = 0,
                n = 0;
              for (const def of C().enemies.values()) {
                let E;
                try {
                  E = enemyAt(def, nv.canhGioi, tc);
                } catch {
                  continue;
                }
                n++;
                if (fight(P, E).thang) w++;
              }
              res.push(
                `<div class="vk-row"><span>Quái ${esc(realmName(nv.canhGioi))} ${STAGE[tc]}</span><b>thắng ${w}/${n} (${pct(w / Math.max(1, n))})</b></div>`,
              );
              out.innerHTML = res.join("");
              await sleep0();
            }
            let w = 0,
              n = 0;
            for (const def of C().enemies.values()) {
              let E;
              try {
                E = enemyAt(def, nv.canhGioi + 1, 0);
              } catch {
                continue;
              }
              n++;
              if (fight(P, E).thang) w++;
            }
            res.push(
              `<div class="vk-row"><span>Quái ${esc(realmName(nv.canhGioi + 1))} Sơ</span><b>thắng ${w}/${n} (${pct(w / Math.max(1, n))})</b></div>`,
            );
            out.innerHTML =
              res.join("") +
              '<div class="vk-mu" style="font-size:12px">Tính với kinh mạch đang xếp trong game.</div>';
          };
        }

